const view=document.querySelector('#screen');
const state={location:'Koramangala, Bengaluru',category:'Medical emergency',contact:'',note:'',recorded:false,accepted:false};
const clean=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const step=(n,label)=>`<p class="step">${n} / ${label}</p>`;
const notice=(heading,copy,neutral=false)=>`<div class="notice${neutral?' neutral':''}"><strong>${heading}</strong>${copy}</div>`;
const action=(label,next,kind='primary')=>`<button type="button" class="${kind}" data-next="${next}">${label}</button>`;
const summary=()=>`<div class="summary"><div class="summary-row"><span>Pickup point · sample</span><strong>${clean(state.location)}</strong></div><div class="summary-row"><span>Type of help</span><strong>${clean(state.category)}</strong></div><div class="summary-row"><span>Contact · sample only</span><strong>${clean(state.contact)}</strong></div>${state.note?`<div class="summary-row"><span>Additional context</span><strong>${clean(state.note)}</strong></div>`:''}</div>`;
const call='<a class="secondary" href="tel:112" style="display:grid;place-items:center">Call 112 for real help</a>';
function home(){return `<div class="screen-inner">${step('01','Start')}<h2>Get help, clearly.</h2><p class="lead">A short path to explore an emergency request experience.</p>${notice('Prototype only — no request is sent','This demonstration does not contact any hospital, ambulance, or emergency service.')}<div class="illustration" role="img" aria-label="Illustration of an ambulance near a hospital"><span class="ambulance"><b>✚</b></span></div><div class="field"><label for="pickup">Pickup location · sample</label><input id="pickup" value="${clean(state.location)}" autocomplete="off" maxlength="100" required><small>Edit this sample place to explore the flow. Do not enter a real address.</small></div><div class="actions">${action('Start sample request','details')}${call}</div></div>`}
function details(){return `<div class="screen-inner">${step('02','Details')}<h2>What kind of help?</h2><p class="lead">Only the essentials for this sample request.</p><form id="details-form" novalidate><div class="field"><label for="category">Emergency type</label><select id="category" required>${['Medical emergency','Road accident','Other urgent help'].map(c=>`<option ${state.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label for="contact">Contact number · sample</label><input id="contact" type="tel" inputmode="numeric" autocomplete="off" pattern="[0-9]{10}" maxlength="10" placeholder="10 sample digits" value="${clean(state.contact)}" required><small>Use a fictitious 10-digit number. It stays in this page only.</small></div><div class="field"><label for="note">Anything else? <span style="font-weight:400">Optional</span></label><textarea id="note" maxlength="240" placeholder="Sample context only">${clean(state.note)}</textarea></div><p id="form-error" class="form-error" role="alert" hidden></p><div class="actions"><button class="primary" type="submit">Review sample request</button>${action('Back to start','home','quiet')}</div></form></div>`}
function review(){return `<div class="screen-inner">${step('03','Review')}<h2>Check the details.</h2><p class="lead">Review what the prototype will show. Nothing will be transmitted.</p>${summary()}${notice('This is a simulation','Continue to record a sample request locally, or choose a failed-send scenario.')}<div class="actions">${action('Record sample request','waiting')}${action('Simulate send failure','failed','secondary')}${action('Edit details','details','quiet')}</div></div>`}
function waiting(){return `<div class="screen-inner">${step('04','Status')}<div class="status-icon" aria-hidden="true">⌛</div><h2>Sample request recorded locally.</h2><p class="lead">Your details are held in this page for the demonstration.</p>${notice('No hospital has received this','This prototype is not connected to dispatch. A local screen state is not delivery confirmation.')}<ol class="timeline"><li class="done"><strong>Sample request recorded</strong><small>Only in this browser page.</small></li><li><strong>Hospital response · simulated</strong><small>Try the next state to explore the design.</small></li></ol><div class="actions">${action('Simulate hospital acceptance','assigned','primary teal')}${call}${action('Start over','home','quiet')}</div></div>`}
function assigned(){return `<div class="screen-inner">${step('05','Simulated response')}<div class="status-icon" aria-hidden="true">✓</div><h2>Acceptance simulated.</h2><p class="lead">This screen illustrates what a verified provider response could look like in a connected service.</p>${notice('Demo state only','No hospital accepted a real request, no ambulance was assigned, and no ETA is available.',true)}<ol class="timeline"><li class="done"><strong>Sample request recorded</strong><small>Locally in this page.</small></li><li class="done"><strong>Acceptance simulated</strong><small>Triggered by your demo action, not a provider.</small></li></ol><div class="actions">${call}${action('Start a new demo','home','quiet')}</div></div>`}
function failed(){return `<div class="screen-inner">${step('04','Failure recovery')}<div class="status-icon error" aria-hidden="true">!</div><h2>Sample request not recorded.</h2><p class="lead">This is the simulated failure path. Your entered details are still available.</p>${notice('No hospital received a request','Nothing was sent. In a real emergency, call 112 now.')}<div class="actions">${call}${action('Try sample recording again','waiting','primary teal')}${action('Edit details','details','quiet')}</div><p class="fine">Retry in this prototype changes only the local demonstration state.</p></div>`}
const screens={home,details,review,waiting,assigned,failed};
function navigate(name){if(name==='waiting')state.recorded=true;if(name==='failed')state.recorded=false;if(name==='assigned'){if(!state.recorded){location.hash='#home';return}state.accepted=true}if(name==='home'){state.recorded=false;state.accepted=false}location.hash=`#${name}`;render()}
function render(){let name=location.hash.slice(1)||'home';if(!screens[name])name='home';if((name==='waiting'||name==='assigned')&&!state.recorded)name='home';view.innerHTML=screens[name]();view.focus({preventScroll:true});scrollTo({top:0,behavior:'instant'})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-next]');if(!b)return;if(b.dataset.next==='details'&&location.hash!=='#review'){const input=document.querySelector('#pickup');if(input){if(!input.value.trim()){input.reportValidity();return}state.location=input.value.trim()}}navigate(b.dataset.next)});
document.addEventListener('submit',e=>{if(e.target.id!=='details-form')return;e.preventDefault();const f=e.target,contact=f.querySelector('#contact'),err=f.querySelector('#form-error');if(!f.checkValidity()){err.textContent='Enter a fictitious 10-digit number to continue.';err.hidden=false;contact.reportValidity();return}state.category=f.querySelector('#category').value;state.contact=contact.value;state.note=f.querySelector('#note').value.trim();navigate('review')});
addEventListener('hashchange',render);render();

